package fixture

import (
	"bytes"
	"errors"
	"io"
	"testing"

	"tsrebuild/internal/inspect"
	"tsrebuild/internal/pipeline"
	"tsrebuild/internal/program"
	"tsrebuild/internal/tsreader"
)

// rawScan independently walks the generated bytes: every 188-byte block must
// start with the sync byte, and counts per PID are summed without trusting the
// manifest, so manifest and packet sequence can be cross-checked.
func rawScan(t *testing.T, data []byte) map[uint16]int {
	t.Helper()
	if len(data)%tsreader.PacketSize != 0 {
		t.Fatalf("stream length %d is not a multiple of 188", len(data))
	}
	counts := make(map[uint16]int)
	for off := 0; off < len(data); off += tsreader.PacketSize {
		if data[off] != tsreader.SyncByte {
			t.Fatalf("packet %d missing sync byte", off/tsreader.PacketSize)
		}
		pid := uint16(data[off+1]&0x1f)<<8 | uint16(data[off+2])
		counts[pid]++
	}
	return counts
}

func generate(t *testing.T, opts Options) ([]byte, *Manifest) {
	t.Helper()
	var buf bytes.Buffer
	m, err := Generate(&buf, opts)
	if err != nil {
		t.Fatal(err)
	}
	return buf.Bytes(), m
}

func TestGenerateRemapLossManifestAndPackets(t *testing.T) {
	data, m := generate(t, Options{Scenario: ScenarioRemap})
	if m.Scenario != ScenarioRemap || m.TotalPackets != int64(len(data)/188) {
		t.Fatalf("manifest total mismatch: %+v", m)
	}
	if len(m.Phases) != 2 {
		t.Fatalf("expected 2 phases, got %d", len(m.Phases))
	}
	ph0, ph1 := m.Phases[0], m.Phases[1]
	if ph0.PATVersion != 0 || ph0.PMTVersion != 0 || ph0.VideoPID != PIDVideoV0 {
		t.Fatalf("phase 0 mapping wrong: %+v", ph0)
	}
	if ph1.PATVersion != 1 || ph1.PMTVersion != 1 || ph1.VideoPID != PIDVideoV1 || ph1.AudioGaps != 1 {
		t.Fatalf("phase 1 mapping wrong: %+v", ph1)
	}
	if ph0.EndPacket != ph1.StartPacket {
		t.Fatal("phases must be contiguous half-open ranges")
	}

	counts := rawScan(t, data)
	// Each of the 10 cycles emits one PAT and one PMT packet.
	if counts[PIDPAT] != 10 || counts[PIDPMT] != 10 {
		t.Fatalf("PSI packet counts wrong: %+v", counts)
	}
	if counts[PIDVideoV0] != 5 || counts[PIDVideoV1] != 5 || counts[PIDAudio] != 10 {
		t.Fatalf("ES counts wrong: %+v", counts)
	}
	if int64(counts[PIDPAT]+counts[PIDPMT]+counts[PIDVideoV0]+counts[PIDVideoV1]+counts[PIDAudio]) != m.TotalPackets {
		t.Fatal("per-PID counts do not add up to total packets")
	}
}

// runPipeline drives the real engine over a generated stream.
func runPipeline(t *testing.T, data []byte, programNumber uint16) (*program.Timeline, inspect.Result) {
	t.Helper()
	eng := pipeline.New(bytes.NewReader(data), programNumber)
	for {
		if _, err := eng.Next(); errors.Is(err, io.EOF) {
			break
		} else if err != nil {
			t.Fatalf("pipeline failed: %v", err)
		}
	}
	tl := eng.Timeline()
	if tl == nil {
		t.Fatal("no mapping committed")
	}
	return tl, eng.Stats()
}

func TestPipelineOnRemapLoss(t *testing.T) {
	data, m := generate(t, Options{Scenario: ScenarioRemap})
	tl, res := runPipeline(t, data, 1)

	if tl.PATVersionChanges() != 1 || tl.PMTVersionChanges(1) != 1 {
		t.Fatalf("version changes wrong: pat=%d pmt=%d", tl.PATVersionChanges(), tl.PMTVersionChanges(1))
	}
	if len(tl.Intervals(1)) != 2 {
		t.Fatalf("expected 2 mapping intervals")
	}
	if len(res.Intervals) != 2 {
		t.Fatalf("expected 2 stat groups, got %d", len(res.Intervals))
	}
	// PID 256 counted only in phase 0, PID 300 only in phase 1.
	pre, post := res.Intervals[0], res.Intervals[1]
	var v0, v1, audioPre, audioPost *inspect.PIDStats
	for i := range pre {
		switch pre[i].PID {
		case PIDVideoV0:
			v0 = &pre[i]
		case PIDAudio:
			audioPre = &pre[i]
		}
	}
	for i := range post {
		switch post[i].PID {
		case PIDVideoV1:
			v1 = &post[i]
		case PIDAudio:
			audioPost = &post[i]
		}
	}
	if v0 == nil || v0.Packets != int64(m.Phases[0].VideoPackets) {
		t.Fatalf("old video attribution wrong: %+v", v0)
	}
	if v1 == nil || v1.Packets != int64(m.Phases[1].VideoPackets) {
		t.Fatalf("new video attribution wrong: %+v", v1)
	}
	if audioPre == nil || audioPost == nil {
		t.Fatal("audio must be present in both intervals")
	}
	if audioPre.Packets+audioPost.Packets != 10 || audioPre.ContinuityGaps+audioPost.ContinuityGaps != 1 {
		t.Fatalf("audio counts wrong: pre=%+v post=%+v", audioPre, audioPost)
	}
}

func TestPipelineBadCRCKeepsMapping(t *testing.T) {
	data, m := generate(t, Options{Scenario: ScenarioBadCRC})
	tl, res := runPipeline(t, data, 1)

	if tl.PATVersionChanges() != 0 || tl.PMTVersionChanges(1) != 0 {
		t.Fatalf("corrupt update must not create a version: pat=%d pmt=%d",
			tl.PATVersionChanges(), tl.PMTVersionChanges(1))
	}
	if len(m.BadCRCPackets) == 0 {
		t.Fatal("manifest should record bad-CRC packets")
	}
	// All video stays on the original PID across the single interval.
	if len(res.Intervals) != 1 {
		t.Fatalf("corrupt table must not open an interval, got %d", len(res.Intervals))
	}
	var video *inspect.PIDStats
	for i := range res.Intervals[0] {
		if res.Intervals[0][i].PID == PIDVideoV0 {
			video = &res.Intervals[0][i]
		}
	}
	if video == nil || video.Packets != 6 {
		t.Fatalf("video should keep 6 packets on PID 256, got %+v", video)
	}
}

func TestPipelineFragmentedPSI(t *testing.T) {
	data, _ := generate(t, Options{Scenario: ScenarioFragment, PSIFragmentSize: 40})
	rawScan(t, data)
	tl, res := runPipeline(t, data, 1)
	if tl.PATVersionChanges() != 1 || tl.PMTVersionChanges(1) != 1 {
		t.Fatalf("fragmented table changes wrong: pat=%d pmt=%d",
			tl.PATVersionChanges(), tl.PMTVersionChanges(1))
	}
	if len(res.Intervals) != 2 {
		t.Fatalf("expected 2 intervals across fragmented remap")
	}
}

func TestGenerateBasicSteady(t *testing.T) {
	data, _ := generate(t, Options{Scenario: ScenarioBasic})
	counts := rawScan(t, data)
	if counts[PIDVideoV0] != 6 || counts[PIDVideoV1] != 0 {
		t.Fatalf("basic scenario counts wrong: %+v", counts)
	}
	tl, _ := runPipeline(t, data, 1)
	if tl.PATVersionChanges() != 0 || tl.PMTVersionChanges(1) != 0 {
		t.Fatal("steady stream must report no version changes")
	}
}
